PRAGMA foreign_keys=ON;
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),sync_enabled INTEGER NOT NULL DEFAULT 1 CHECK(sync_enabled IN (0,1)),revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0));
INSERT INTO settings(id) VALUES(1);
CREATE TABLE connections(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL,observed_at TEXT NOT NULL,last_admitted_at TEXT,next_import_at TEXT,last_success_at TEXT);
CREATE TRIGGER connection_limit BEFORE INSERT ON connections WHEN (SELECT count(*) FROM connections)>=10 AND NOT EXISTS(SELECT 1 FROM connections WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'ITEM_LIMIT'); END;
CREATE TABLE accounts(connection_id TEXT NOT NULL REFERENCES connections(id),id TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('BANK','CREDIT')),currency TEXT NOT NULL,balance_minor TEXT,source_updated_at TEXT,observed_at TEXT NOT NULL,source TEXT NOT NULL CHECK(json_valid(source)),last_seen_run TEXT NOT NULL,last_completed_run TEXT,collection_status TEXT NOT NULL DEFAULT 'never',last_attempt_at TEXT,last_success_at TEXT,last_completed_from TEXT,last_completed_to TEXT,observed_from TEXT,observed_to TEXT,error TEXT,PRIMARY KEY(connection_id,id));
CREATE TABLE transactions(connection_id TEXT NOT NULL,account_id TEXT NOT NULL,id TEXT NOT NULL,date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PENDING','POSTED')),direction TEXT NOT NULL CHECK(direction IN ('DEBIT','CREDIT')),currency TEXT NOT NULL,amount_minor TEXT,description TEXT NOT NULL,category TEXT,classification TEXT NOT NULL,evidence TEXT NOT NULL CHECK(json_valid(evidence)),source_updated_at TEXT,observed_at TEXT NOT NULL,source TEXT NOT NULL CHECK(json_valid(source)),last_seen_run TEXT NOT NULL,category_override TEXT,description_override TEXT,ignored_override INTEGER CHECK(ignored_override IS NULL OR ignored_override IN (0,1)),corrected_at TEXT,PRIMARY KEY(connection_id,account_id,id),FOREIGN KEY(connection_id,account_id) REFERENCES accounts(connection_id,id));
CREATE INDEX transaction_date ON transactions(date,connection_id,account_id,id);
CREATE INDEX transaction_account ON transactions(connection_id,account_id,date,id);
CREATE INDEX transaction_presence ON transactions(connection_id,account_id,last_seen_run,date,id);
CREATE INDEX transaction_status ON transactions(status,date);
CREATE INDEX transaction_category ON transactions(coalesce(category_override,category));
CREATE TABLE sync_runs(id TEXT PRIMARY KEY,connection_id TEXT NOT NULL REFERENCES connections(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','succeeded','failed')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,sequence INTEGER NOT NULL DEFAULT 0 CHECK(sequence>=0),checkpoint TEXT NOT NULL CHECK(json_valid(checkpoint)),last_commit_id TEXT,last_result TEXT,records INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE UNIQUE INDEX one_active_import ON sync_runs(connection_id) WHERE status IN ('pending','running');
CREATE INDEX run_created ON sync_runs(created_at);
